    "C49", "C55", "C58"
  ],
  "contradictory_card_ids": [
    "C28", "C39", "C40"
  ],
  "prediction_basis_card_ids": [
    "C04", "C06", "C14", "C01", "C05",
    "C10", "C21", "C13", "C19", "C22", "C30",
    "C08", "C15", "C18", "C26"
  ],
  "claims": [
    {
      "claim": "Verapamil, the most transferable context (dimethoxyphenyl tertiary amine), has absolute oral bioavailability values of 52 ± 13%, 52.3%, 38.17%, and 22% in cirrhosis patients, all at or above the 20% threshold.",
      "card_ids": ["C04", "C06", "C09", "C20", "C43", "C48"]
    },
    {
      "claim": "Valbenazine, which shares a dimethoxy-substituted fused bicyclic core and basic amine, has absolute oral bioavailability of approximately 49% in humans.",
      "card_ids": ["C14", "C33", "C34"]
    },
    {
      "claim": "Encainide, a basic methoxy-substituted aryl amide, has mean absolute oral bioavailability of 42 ± 24% (range 7.4–82%) and 41.9%, with a 30 ± 7% record; the mean supports F ≥ 20% despite wide variability.",
      "card_ids": ["C01", "C02", "C05", "C37", "C41"]
    },
    {
      "claim": "Noscapine, a polymethoxylated alkaloid, has human oral bioavailability of about 30–31% and mouse F of 26.68 ± 3.8%; the qualitative 'poor' descriptor reflects high-dose requirements, not a sub-20% absolute F.",
      "card_ids": ["C08", "C15", "C18", "C26", "C38", "C39"]
    },
    {
      "claim": "Sulpiride/levosulpiride, basic methoxy-substituted drugs, show human absolute F of about 24.8–35% (F_AUC 0.248, F_U 0.280; ~27–35%), above threshold; the rat value of 15% is species-limited.",
      "card_ids": ["C10", "C21", "C27", "C36", "C13", "C19", "C22", "C30", "C40"]
    },
    {
      "claim": "The only clear low record, alfentanil F = 1% (C28), conflicts with other alfentanil records of 37–45% (C03, C25, C31, C45) and is not structurally similar to the query, so it does not support a low prediction.",
      "card_ids": ["C28", "C03", "C25", "C31", "C45"]
    },
    {
      "claim": "Additional less similar contexts also report F values above 20%: codeine 40–90%, colchicine 25–55%, and praziquantel 27.2% in cirrhosis, reinforcing the high direction.",
      "card_ids": ["C12", "C17", "C23", "C29", "C11", "C35", "C16"]
    },
    {
      "claim": "L3 oral AUC/Cmax records for verapamil (C49), donepezil (C55), prazosin (C58), and other basic/methoxy-substituted molecules show measurable oral exposure, consistent with oral absorption but not direct F evidence for the query.",
      "card_ids": ["C49", "C55", "C58"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C49", "C50", "C51", "C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule itself.",
    "L3 records report oral AUC/Cmax but lack matched IV comparators, so they do not directly quantify absolute F.",
    "Transfer relies on structural analogy; exact first-pass, lactam metabolism, and transporter effects of the query are unknown.",
    "Verapamil cirrhosis records vary (22–52%) and the alfentanil 1% outlier is unresolved.",
    "No formulation, dose, or fed/fasted data are available for the query.",
    "L3 records are non-gold mechanistic context, not independent endpoint measurements."
  ],
  "decision_summary": "Predicted high (F ≥ 20%) because the most transferable L1/L2 contexts (verapamil, valbenazine, encainide, noscapine, sulpiride/levosulpiride) consistently show absolute oral bioavailability above 20%; L3 oral AUC/Cmax records for structurally similar molecules are consistent with oral exposure but do not provide direct F evidence, so the prior high prediction is retained without further strengthening."
}

